updated AS (
  UPDATE clients c
     SET client_phone = changes.new_phone
    FROM changes
   WHERE c.id = changes.id::uuid
     AND c.client_phone = changes.old_phone
     AND c.deleted_at IS NULL
  RETURNING 1
)
SELECT count(*) AS clients_updated FROM updated;   -- expect 1020

