-- ─────────────────────────────────────────────────────────────────────────────
-- STEP 2 — Confirm
-- ─────────────────────────────────────────────────────────────────────────────
-- Expect not_e164_shaped = 145 (it was 1143 in STEP 0). Those 145 are rows that share their
-- number with another client and were left for the duplicate-merge review; 3 more such rows are
-- already E.164-shaped, so the shape test does not count them. A result near 1143 means STEP 1
-- did not run (it rolled back as a whole).
SELECT count(*) FILTER (WHERE client_phone !~ '^[+][1-9][0-9]{6,14}$')::int AS not_e164_shaped
FROM clients
WHERE deleted_at IS NULL AND client_phone IS NOT NULL AND btrim(client_phone) <> '';
